      "name": "release_pulse",
      "value": "2.0",
      "units": "s",
      "narrative_section": "3. ST10 — Pallet conveyor"
    },
    {
      "name": "jam_time",
      "value": "5.0",
      "units": "s",
      "narrative_section": "3. ST10 — Pallet conveyor"
    }
  ],
  "steps": [
    {
      "name": "Conveyor Running",
      "entry": "Auto mode SS-0003 (X2) active, no ST10 fault present, and E-stop healthy",
      "exit": "Auto mode lost, ST10 fault occurs (motor overload or jam), or E-stop chain lost"
    },
    {
      "name": "Stopper Release",
      "entry": "Rising edge of line controller release request RQ-1005 (X14)",
      "exit": "Stopper release timer T11 reaches 2.0 s preset"
    }
  ],
  "interlocks": [
    {
      "cause": "Motor overload MOL-1001 (X13 lost) or E-stop chain lost (X0 lost)",
      "effect": "Conveyor motor M-1001 (Y10) stops immediately"
    },
    {
      "cause": "Pallet at stop PE-1001 (X10)",
      "effect": "Reports pallet in position (M100) to ST20"
    },
    {
      "cause": "Line controller release request RQ-1005 (X14) rising edge",
      "effect": "Energises stopper solenoid XY-1004 (Y11) for 2.0 s"
    }
  ],
  "alarms": [
    {
      "name": "Motor Overload Alarm",
      "condition": "Motor overload contact MOL-1001 opens (X13 is OFF)",
      "action": "Stops conveyor motor immediately (M191/M199 set)"
    },
    {
      "name": "Conveyor Jam Alarm",
      "condition": "Entry photo-eye PE-1002 stays blocked for more than 5.0 s while conveyor runs",
      "action": "Conveyor stops and jam alarm (M190) is raised until reset by PB-0002 (X1)"
    }
  ],
  "conflicts": [
    {
      "item": "jam_time implementation",
      "narrative_says": "If entry photo-eye PE-1002 stays blocked for more than 5.0 s while conveyor runs, conveyor stops and jam alarm is raised",
      "parameter_sheet_says": "jam_time = 5.0 s (T10)",
      "program_says": "Timer T10 and detection logic for entry photo-eye PE-1002 are missing from the ST10 program entirely",
      "authoritative": "parameters"
    },
    {
      "item": "E-stop logic in conveyor interlock (R3)",
      "narrative_says": "A motor overload or the E-stop chain stops the conveyor immediately (stopping when E-stop is lost)",
      "parameter_sheet_says": "N/A",
      "program_says": "R3 uses ORI X0 to set M199, which turns on fault flag M199 when E-stop is healthy (X0 ON) instead of when E-stop is tripped (X0 OFF)",
      "authoritative": "parameters"
    }
  ]
}
